-- 060 - The public pages that the Compliance and Services menus open (Payroll & IR, Social Security, Health & Safety, Environmental, Service & Global Certification, Training, Audit Structure).
--       They were created on the development database by script and never existed on the live one, so every menu entry that led to them showed a blank "404: This page could not be found".
--       A page that is missing is created (published, with its text, including the client's own text from migration 056); a page that exists is left as the client edited it, only
--       made visible again if it was unpublished or deleted by accident, because the menu points at it.
SET NAMES utf8mb4;

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'payroll-compliance-ir', 'Payroll, Compliance and IR Management', 'Smart Workforce, full and final settlement and the industrial relations matters that sit around them.', 'Payroll, Compliance and IR Management', 'Smart Workforce, full and final settlement and the industrial relations matters that sit around them.', '<h2>Wages, Working Hours &amp; Conditions of Employment</h2><p>NextGen supports organisations in developing transparent and legally compliant systems relating to wages, working hours, overtime, leave, attendance, payslips, wage records and employment conditions.</p><p>The objective is to promote fair and transparent wage administration while preventing wage-related disputes, discrimination and unfair labour practices. We assist organisations in reviewing their wage structures and employment practices against applicable statutory requirements and identifying areas requiring corrective action.</p><h2>Industrial Relations &amp; Grievance Redressal</h2><p>Healthy industrial relations are essential for sustainable organisational performance. NextGen assists management in establishing professional systems for employee communication, grievance handling, dispute prevention, disciplinary procedures, domestic enquiries and employer–employee relationship management.</p><p>We support the development of structured grievance-redressal mechanisms through which workers can raise concerns in a transparent, confidential and timely manner. Effective grievance management can help organisations identify workplace issues at an early stage and prevent them from developing into larger disputes.</p><h2>Smart Workforce</h2><p>One record for every employee, from the personal file to the payslip. Employers keep the personal file with its checklist and pre-filled forms (appointment order, confirmation letter, Form F, EPF Form 2 and Form 11, wage acceptance through bank, service record), run payroll with the statutory wage register and a bilingual service card payslip, and let each employee check in, check out and ask for permission from their own profile.</p><h2>Full and final settlement</h2><p>Part-month salary, leave encashment, bonus and gratuity on one side, notice and other recoveries on the other, with the net figure in words and an acknowledgement for the employee to sign.</p><h2>Industrial relations</h2><p>Advice and documentation on the matters employers most often need to get right:</p><ul><li>Grievance redressal procedure and records</li><li>Standing orders</li><li>Strikes and lockouts: notice and procedure</li><li>Layoff and retrenchment: conditions, notice and compensation</li><li>Provident fund, ESI, bonus and gratuity: calculation and returns</li></ul><p>Try the <a href="/calculators?tool=gratuity">payroll calculators</a> for EPF, ESI, gratuity, bonus and overtime.</p>', 'page', 'default', 3, 1, 'Payroll, Compliance and IR Management', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'payroll-compliance-ir');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'social-security-compliance', 'Social Security Compliance Management', 'EPF, ESI, bonus, gratuity and welfare fund: registration, calculation, returns and records.', 'Social Security Compliance Management', 'EPF, ESI, bonus, gratuity and welfare fund: registration, calculation, returns and records.', '<h2>Social Security Compliance</h2><p>The Compliance Wing assists organisations in establishing effective systems for statutory social-security compliance, including applicable provisions relating to Employees’ Provident Fund, Employees’ State Insurance, gratuity, bonus, employee insurance, welfare benefits and other applicable statutory schemes.</p><p>Our services include compliance-gap identification, registration and contribution monitoring, statutory documentation, employee-benefit awareness and record-management support. Particular emphasis is placed on ensuring that eligible employees understand their statutory rights and that organisations maintain appropriate systems for timely implementation of applicable benefits.</p><h2>What is covered</h2><ul><li>Provident fund (EPF and pension): registration, contribution and monthly returns</li><li>Employees'' State Insurance: coverage, contribution and half-yearly returns</li><li>Payment of Bonus: eligibility, calculation and register</li><li>Payment of Gratuity: eligibility, calculation and nomination (Form F)</li><li>Labour welfare fund and professional tax: due dates and remittance</li></ul><h2>How we help</h2><p>We check the numbers on your payslips against the statutory rules, keep the registers an inspector asks for, and track every due date on the compliance calendar. Employees'' nominations (EPF Form 2, Form F) and declarations (Form 11) are kept in the personal file.</p><p>See the <a href="/compliance-calendar-guide">compliance calendar</a> and the <a href="/calculators?tool=epf">EPF and ESI calculators</a>.</p>', 'page', 'default', 4, 1, 'Social Security Compliance Management', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'social-security-compliance');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'health-safety-compliance', 'Health and Safety Compliance Management', 'Safety audits, assessments, risk engineering and the permits that control hazardous work.', 'Health and Safety Compliance Management', 'Safety audits, assessments, risk engineering and the permits that control hazardous work.', '<h2>Industrial Safety &amp; Occupational Health</h2><p>NextGen provides professional assistance in establishing and strengthening industrial safety and occupational health management systems. This includes support for compliance with applicable occupational safety legislation, factory safety requirements, fire and life-safety provisions, electrical safety requirements, machinery safety, chemical safety and other workplace safety obligations.</p><p>Our safety services include Hazard Identification and Risk Assessment (HIRA), Job Safety Analysis (JSA), risk assessment, safety audits, workplace inspections, machine safety assessments, electrical safety assessments, chemical safety assessments, emergency preparedness, Permit-to-Work systems, PPE management, safety committees, accident investigation and corrective-action management.</p><p>We also support organisations in developing Emergency Response Plans (ERP), on-site emergency procedures, evacuation arrangements, emergency communication systems, mock-drill programmes and incident-response mechanisms. Safety awareness is strengthened through worker training, toolbox talks, induction programmes, supervisor training and continuous safety communication.</p><p>The ultimate objective is to develop a positive safety culture in which management and workers jointly participate in hazard prevention, safe working practices and continuous improvement.</p><h2>Safety audit</h2><p>Statutory safety audit against IS 14489, the Factories Act and the State Factories Rules, with chapter-wise compliance, non-conformities and a corrective action plan.</p><h2>Assessments and risk engineering</h2><ul><li>HIRA and risk registers (likelihood x consequence)</li><li>HAZOP studies for process hazards</li><li>Fire safety audit, fire load and fire protection calculations</li><li>Lifting calculations and safety performance rates</li><li>Risk assessments for safety, environment, water, waste, energy and chemicals</li></ul><h2>Work permits</h2><p>Permit-to-work for hot work, work at height, lifting, confined space entry, electrical isolation (lock-out tag-out), cold work and excavation.</p><h2>Reports</h2><p>Every audit ends in a report with findings, a corrective and preventive action plan with owners and timelines, and verification by a reviewer before it is approved. Work out injury rates with the <a href="/calculators?tool=rates">safety calculators</a>.</p>', 'page', 'default', 5, 1, 'Health and Safety Compliance Management', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'health-safety-compliance');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'environmental-compliance', 'Environmental Compliance Management', 'Environmental audits and assessments, effluent treatment, groundwater, waste, energy and carbon.', 'Environmental Compliance Management', 'Environmental audits and assessments, effluent treatment, groundwater, waste, energy and carbon.', '<h2>Environmental, Social &amp; Governance (ESG)</h2><p>NextGen assists organisations in developing and implementing ESG frameworks that integrate environmental performance, social responsibility and governance practices into organisational decision-making.</p><p>Our services may include ESG gap assessments, materiality-related support, environmental and social performance indicators, data collection systems, ESG documentation, reporting support and stakeholder communication.</p><p>The objective is to establish measurable systems through which organisations can understand and demonstrate their performance in areas such as environmental impact, employee welfare, occupational safety, resource consumption, waste management, ethical governance and social responsibility.</p><h2>Net Zero &amp; Climate Action</h2><p>NextGen supports organisations in understanding and managing their greenhouse-gas emissions through carbon-footprint assessment and climate-management programmes.</p><p>Our services may include assessment of Scope 1, Scope 2 and relevant Scope 3 emissions, identification of major emission sources, energy-efficiency opportunities, renewable-energy integration, emission-reduction strategies and development of practical Net Zero roadmaps.</p><p>The approach focuses first on measurement and reduction, followed by appropriate management of residual emissions in accordance with applicable frameworks and organisational objectives. We also support organisations in developing climate-resilience and resource-efficiency strategies.</p><h2>Environmental Compliance &amp; Governance</h2><p>The Environment Wing assists industries and organisations in meeting applicable environmental requirements under relevant environmental legislation, regulatory conditions, consent requirements and waste-management regulations.</p><p>Our services cover areas such as Water Act and Air Act compliance, Environmental Protection requirements, hazardous-waste management, solid-waste management, plastic-waste management, biomedical-waste management, wastewater management, ETP assessment, STP assessment, ZLD systems, environmental audits, water audits, waste audits, pollution-control systems and environmental documentation.</p><p>We also support organisations in improving resource efficiency through water conservation, wastewater recycling and reuse, energy efficiency, waste minimisation, material recovery and circular-economy approaches.</p><p>Particular attention is given to industries generating complex wastewater streams, including wastewater treatment systems involving ETP, RO, MEE and ZLD processes, where appropriate assessment of waste characteristics, salt generation, recovery possibilities, recycling opportunities and environmentally sound disposal methods can contribute to improved resource efficiency.</p><h2>Audits and assessments</h2><ul><li>Environmental compliance audit against consents and authorisations</li><li>ETP, STP and CETP functionality assessment with a green, yellow or red grade</li><li>TSDF audit and hazardous waste records</li><li>Energy audit and greenhouse gas inventory verification</li></ul><h2>Groundwater and water</h2><p>The groundwater NOC with its conditions, the water meter log, and the water drawn against the approved quantity, shown as a daily figure and a monthly trend.</p><h2>Returns and forms</h2><p>Environmental statement (Form V), hazardous waste returns and the consent renewals due under the Water, Air, Hazardous Waste, E-Waste and Plastic Waste rules, tracked on the compliance calendar.</p><h2>Corrective action</h2><p>Non-compliances found in an audit go into a corrective and preventive action report: the Act and Rule, the minimum requirement, the finding with photographs, the root cause, the action plan, the timeline and evidence, verified by a reviewer.</p><p>Use the <a href="/calculators?tool=emissions">environmental calculators</a> for emissions, effluent load and water balance.</p>', 'page', 'default', 6, 1, 'Environmental Compliance Management', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'environmental-compliance');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'audit-structure', 'Audit Structure', 'How an audit moves from assignment to an approved report on the platform.', 'Audit Structure', 'How an audit moves from assignment to an approved report on the platform.', '<h2>The flow</h2><ol><li><strong>Assignment.</strong> An audit is assigned to an auditor of the matching type.</li><li><strong>Fieldwork.</strong> The auditor fills the audit form, records findings and uploads evidence.</li><li><strong>Corrective action.</strong> Each non-compliance gets a root cause, an action plan, a timeline and evidence.</li><li><strong>Verification.</strong> A reviewer verifies each finding and approves or returns the report.</li><li><strong>Report.</strong> The approved report is printed on the company letterhead and shared with the client.</li></ol><h2>Auditor types</h2><ul><li>Water auditor: water balance, groundwater NOC and meter readings</li><li>Environmental auditor: consents, ETP / STP / CETP, waste</li><li>Energy and GHG auditor: energy audit and carbon inventory</li><li>Safety auditor: IS 14489 safety audit, risk assessment, permits</li><li>Fire safety auditor: fire audit and protection</li><li>Legal and statutory auditor: legal registers and calendars</li><li>Social compliance auditor: WRAP, SMETA, training</li><li>Payroll auditor: payroll and wage register audit</li><li>Textile standards auditor: GOTS, GRS, OCS, RCS, RWS</li><li>Food safety and electrical safety auditors</li></ul>', 'page', 'default', 7, 1, 'Audit Structure', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'audit-structure');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'service-global-certification', 'Service and Global Certification', 'Preparation and documentation for textile, social and management-system certification audits.', 'Service and Global Certification', 'Preparation and documentation for textile, social and management-system certification audits.', '<h2>Textile standards</h2><p>Document and record readiness for GOTS, GRS, OCS, RCS and RWS audits, including the processing aids, process declarations and reclaimed material declarations they require.</p><h2>Social compliance</h2><p>WRAP and Sedex SMETA style audits: site information, policies, records, training and the corrective actions that follow.</p><h2>Our role</h2><p>We prepare your records and gaps ahead of the certification body''s audit and track the corrective actions afterwards. Certification itself is issued by the standard''s own certification body.</p>', 'page', 'default', 8, 1, 'Service and Global Certification', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'service-global-certification');

INSERT INTO cms_pages (uuid, slug, title, subtitle, meta_title, meta_description, content_html, page_type, template, sort_order, show_in_menu, menu_label, status, published_at)
SELECT UUID(), 'training-capacity-building', 'Training and Capacity Building', 'Toolbox talks and compliance training for workers, supervisors and management.', 'Training and Capacity Building', 'Toolbox talks and compliance training for workers, supervisors and management.', '<h2>Programmes</h2><ul><li>Safety and compliance training plans for the year, with attendance records</li><li>Toolbox talks on the hazards of the week</li><li>Worker rights, grievance and anti-harassment awareness</li><li>Fire, evacuation and first-aid drills</li><li>Statutory compliance for HR, payroll and EHS teams</li></ul><p>Training is planned, delivered and recorded in the same system as your audits, so the evidence an auditor asks for is already on file.</p>', 'page', 'default', 11, 1, 'Training and Capacity Building', 'published', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cms_pages WHERE slug = 'training-capacity-building');

UPDATE cms_pages SET status = 'published', deleted_at = NULL, published_at = COALESCE(published_at, NOW())
WHERE slug IN ('payroll-compliance-ir', 'social-security-compliance', 'health-safety-compliance', 'environmental-compliance', 'service-global-certification', 'training-capacity-building', 'audit-structure') AND (status <> 'published' OR deleted_at IS NOT NULL);
